using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.DTOs;
namespace OrcaFacil.Web.Pages.Documents; [Authorize] public class IndexModel:PageModel{private readonly ICurrentUserService _current; private readonly IDocumentQueries _queries; public IReadOnlyList<DocumentSummaryDto> Documents{get;private set;}=[]; public IndexModel(ICurrentUserService current,IDocumentQueries queries){_current=current;_queries=queries;} public async Task OnGetAsync(CancellationToken ct)=>Documents=await _queries.ListDocumentsAsync(_current.UserId,ct);}
